input.content:
// Multi-rail compute node: STM32F103 + SPI flash + USB-C, 5-12 V in, buck + three LDOs + load switch.
board "multirail_compute_node" {
  layers 4
  manufacturer "jlc-standard"

  stackup {
    copper 0.035mm
    insulator 0.21mm er 4.4 material "FR4"
    copper 0.0175mm
    insulator 1.065mm er 4.6 material "FR4"
    copper 0.0175mm
    insulator 0.21mm er 4.4 material "FR4"
    copper 0.035mm
  }

  // ---- Net classes -------------------------------------------------------
  netclass "PWR"      { trace_width 0.6mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#d55e00" }
  netclass "BUCK_SW"  { trace_width 0.6mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate fast layers "F.Cu" color "#cc0000" }
  netclass "PWR_LOW"  { trace_width 0.3mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#e69f00" }
  netclass "GNDC"     { trace_width 0.4mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#000000" }
  netclass "SIG_SLOW" { trace_width 0.2mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#0072b2" }
  netclass "SPI"      { trace_width 0.2mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm color "#009e73" }
  netclass "USB"      { trace_width 0.2mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm color "#cc79a7" }

  // ---- Power entry -------------------------------------------------------
  group "POWER ENTRY" color "#c2410c" {
    component J2: connector "header_1x2"
    component F1: fuse "polyfuse_1r1a"
    component D1: diode "smaj15a_tvs"
    component D2: diode "ss36"
    component J1: connector "usb_c_receptacle" { escape { off } }
    component F2: fuse "polyfuse_1r1a"
    component D3: diode "ptvs6v0s1ur"
    component D4: diode "d_schottky"
    component R11: resistor "r_generic_0603" value "5.1k"
    component R12: resistor "r_generic_0603" value "5.1k"
    component D5: diode "esd_usb"
    component D6: diode "esd_usb"
    notes "" {
      "DC input 5-12 V: PTC F1, TVS D1 (15 V standoff, 24.4 V clamp), SS36 D2 reverse block."
      "USB VBUS: PTC F2, TVS D3, 1N5819 D4 ORs VBUS into VIN."
    }
  }

  // ---- Buck: VIN -> 3.6 V ------------------------------------------------
  group "BUCK 3V6" color "#cc0000" {
    component U1: regulator "lmr33640" { escape { off } }
    component L1: inductor "l_bourns_srn6045ta_6r8m"
    component C1: capacitor "c_generic_1206" value "10uF"
    component C2: capacitor "c_generic_1206" value "10uF"
    component C3: capacitor "c_generic_0603" value "220nF"
    component C4: capacitor "c_generic_0805" value "22uF"
    component C5: capacitor "c_generic_0805" value "22uF"
    component C6: capacitor "c_generic_0603" value "100nF"
    component C7: capacitor "c_generic_0603" value "1uF"
    component R1: resistor "r_generic_0603" value "100k"
    component R2: resistor "r_generic_0603" value "10k"
    component R3: resistor "r_generic_0603" value "3.83k"
    notes "" {
      "LMR33640 VFB 1.0 V: Vout = 1.0 x (1 + 10k / 3.83k) = 3.611 V."
      "Internal compensation: no external network. L1 6.8 uH, ripple 0.93 A at 12 V in."
    }
  }

  // ---- Linear rails and sequencing --------------------------------------
  group "LDO RAILS" color "#0a7d4a" {
    component U2: regulator "lp5907_3v3"
    component C8: capacitor "c_generic_0603" value "1uF"
    component C9: capacitor "c_generic_0603" value "1uF"
    component U3: regulator "ams1117_1v8"
    component C10: capacitor "c_generic_0805" value "10uF"
    component C11: capacitor "c_generic_0805" value "10uF"
    component R4: resistor "r_generic_0603" value "330"
    component U5: regulator "tps22918_sot23_6"
    component C12: capacitor "c_generic_0603" value "1uF"
    component C13: capacitor "c_generic_0603" value "1nF"
    component C14: capacitor "c_generic_0603" value "1uF"
    component U4: regulator "tlv70012_1v2"
    component C15: capacitor "c_generic_0603" value "1uF"
    component C16: capacitor "c_generic_0603" value "1uF"
    notes "" {
      "3V3 LP5907; 1V8 AMS1117 (R4 is its minimum load); 1V2 TLV70012."
      "Sequence: 3V3 up, then TPS22918 passes 1V8, then 1V8_SW enables the 1V2 LDO."
    }
  }

  // ---- Processor, memory, clock, debug ----------------------------------
  group "COMPUTE CORE" color "#0072b2" {
    component U6: mcu "stm32f103c8_usb" { escape { off } }
    component C20: capacitor "c_generic_0603" value "100nF"
    component C21: capacitor "c_generic_0603" value "100nF"
    component C22: capacitor "c_generic_0603" value "100nF"
    component C23: capacitor "c_generic_0603" value "100nF"
    component C24: capacitor "c_generic_0603" value "100nF"
    component C25: capacitor "c_generic_0805" value "4.7uF"
    component Y1: crystal "xtal_8mhz_3225_4p"
    component C26: capacitor "c_generic_0603" value "10pF"
    component C27: capacitor "c_generic_0603" value "10pF"
    component R9: resistor "r_generic_0603" value "10k"
    component R10: resistor "r_generic_0603" value "10k"
    component R13: resistor "r_generic_0603" value "1.5k"
    component C28: capacitor "c_generic_0603" value "100nF"
    component SW1: switch "spst_tactile"
    component J3: connector "header_1x5_swd"
    component U7: memory "w25q128_flash" { escape { off } }
    component C29: capacitor "c_generic_0603" value "100nF"
    component R14: resistor "r_generic_0603" value "10k"
    component R15: resistor "r_generic_0603" value "10k"
    notes "" {
      "STM32F103C8 needs 3.3 V only; 8 MHz crystal for USB; SWD on J3."
    }
  }

  // ---- Indicators, headers, test points, hardware ------------------------
  group "IO AND TEST" color "#7a3e9d" {
    component D7: diode "led_red_0603"
    component R5: resistor "r_generic_0603" value "680"
    component D8: diode "led_green_0603"
    component R6: resistor "r_generic_0603" value "470"
    component D9: diode "led_amber_0603"
    component R7: resistor "r_generic_0603" value "470"
    component D10: diode "led_amber_0603"
    component R8: resistor "r_generic_0603" value "470"
    component J4: connector "header_1x8"
    component TP1: testpoint "testpoint_pad_1_5"
    component TP2: testpoint "testpoint_pad_1_5"
    component TP3: testpoint "testpoint_pad_1_5"
    component TP4: testpoint "testpoint_pad_1_5"
    component TP5: testpoint "testpoint_pad_1_5"
    component TP6: testpoint "testpoint_pad_1_5"
    component TP7: testpoint "testpoint_pad_1_5"
    component TP8: testpoint "testpoint_pad_1_5"
    component TP9: testpoint "testpoint_pad_1_5"
    component H1: mounting_hole "mounting_hole_m2_5"
    component H2: mounting_hole "mounting_hole_m2_5"
    component FID1: fiducial "fiducial_1mm"
    component FID2: fiducial "fiducial_1mm"
    component FID3: fiducial "fiducial_1mm"
    notes "" {
      "J4 carries 3V6, 3V3, 1V8_SW, 1V2 and two GPIO. TP1 VIN, TP2 3V6, TP3 3V3, TP4 1V8, TP5 1V2, TP6 VBUS, TP7-8 GND, TP9 1V8_SW."
    }
  }

  // ---- Nets: input -------------------------------------------------------
  net "DC_IN"    class "PWR" { J2.p1 F1.p1 }
  net "VIN_RAW"  class "PWR" { F1.p2 D1.cathode D2.anode }
  net "VBUS"     class "PWR" { J1.vbus J1.vbus_b4 J1.vbus_a9 J1.vbus_b9 F2.p1 TP6.p1 }
  net "VBUS_F"   class "PWR" { F2.p2 D3.cathode D4.anode }
  net "VIN"      class "PWR" { D2.cathode D4.cathode U1.vin U1.en C1.p1 C2.p1 C3.p1 TP1.p1 }
  net "GND"      class "GNDC" {
    J2.p2 D1.anode D3.anode
    J1.gnd J1.gnd_b12 J1.gnd_a12 J1.gnd_b1 J1.shld
    R11.p2 R12.p2 D5.gnd D6.gnd
    U1.gnd U1.pad C1.p2 C2.p2 C3.p2 C4.p2 C5.p2 C7.p2 R3.p2
    U2.gnd C8.p2 C9.p2 U3.gnd C10.p2 C11.p2 R4.p2
    U5.gnd C12.p2 C13.p2 C14.p2 U4.gnd C15.p2 C16.p2
    U6.vss U6.vss_2 U6.vss_3 U6.vssa
    C20.p2 C21.p2 C22.p2 C23.p2 C24.p2 C25.p2 C28.p2 C29.p2
    Y1.gnd_2 Y1.gnd_4 C26.p2 C27.p2 R10.p2 SW1.p2 J3.p5 U7.gnd
    D7.cathode D8.cathode D9.cathode D10.cathode
    J4.p5 J4.p8 TP7.p1 TP8.p1
  }

  // ---- Nets: buck --------------------------------------------------------
  net "SW"       class "BUCK_SW" { U1.sw C6.p2 L1.p1 }
  net "BOOT"     class "BUCK_SW" { U1.boot C6.p1 }
  net "VCC_BUCK" class "PWR_LOW" { U1.vcc C7.p1 }
  net "FB"       class "SIG_SLOW" { U1.fb R2.p2 R3.p1 }
  net "PG_3V6"   class "SIG_SLOW" { U1.pg R1.p1 U6.pa0 }
