  netclass "SIG_SLOW" { trace_width 0.2mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#0072b2" }
  netclass "SPI"      { trace_width 0.2mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm color "#009e73" }
  netclass "USB"      { trace_width 0.2mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm color "#cc79a7" }

  // ---- Power entry -------------------------------------------------------
  group "POWER ENTRY" color "#c2410c" {
    component J2: connector "header_1x2"
    component F1: fuse "polyfuse_1r1a"
    component D1: diode "smaj15a_tvs"
    component D2: diode "ss36"
    component J1: connector "usb_c_receptacle" { escape { off } }
    component F2: fuse "polyfuse_1r1a"
    component D3: diode "ptvs6v0s1ur"
    component D4: diode "d_schottky"
    component R11: resistor "r_generic_0603" value "5.1k"
    component R12: resistor "r_generic_0603" value "5.1k"
    component D5: diode "esd_usb"
    component D6: diode "esd_usb"
    component D11: diode "d_tvs_5v"
    component D12: diode "d_tvs_5v"
    component C30: capacitor "c_generic_0805" value "10uF"
    notes "" {
      "DC input 5-12 V: PTC F1, TVS D1 (15 V standoff, 24.4 V clamp), SS36 D2 reverse block."
      "USB VBUS: PTC F2, TVS D3, 1N5819 D4 ORs VBUS into VIN."
    }
  }

  // ---- Buck: VIN -> 3.6 V ------------------------------------------------
  group "BUCK 3V6" color "#cc0000" {
    component U1: regulator "lmr33640" { escape { off } }
    component L1: inductor "l_bourns_srn6045ta_6r8m"
    component C1: capacitor "c_generic_1206" value "10uF"
    component C2: capacitor "c_generic_1206" value "10uF"
    component C3: capacitor "c_generic_0603" value "220nF"
    component C4: capacitor "c_generic_0805" value "22uF"
    component C5: capacitor "c_generic_0805" value "22uF"
    component C6: capacitor "c_generic_0603" value "100nF"
    component C7: capacitor "c_generic_0603" value "1uF"
    component R1: resistor "r_generic_0603" value "100k"
    component R2: resistor "r_generic_0603" value "10k"
    component R3: resistor "r_generic_0603" value "3.83k"
    notes "" {
      "LMR33640 VFB 1.0 V: Vout = 1.0 x (1 + 10k / 3.83k) = 3.611 V."
      "Internal compensation: no external network. L1 6.8 uH, ripple 0.93 A at 12 V in."
    }
  }

  // ---- Linear rails and sequencing --------------------------------------
  group "LDO RAILS" color "#0a7d4a" {
    component U2: regulator "lp5907_3v3"
    component C8: capacitor "c_generic_0603" value "1uF"
    component C9: capacitor "c_generic_0603" value "1uF"
    component U3: regulator "ams1117_1v8"
    component C10: capacitor "c_generic_0805" value "10uF"
    component C11: capacitor "c_generic_0805" value "10uF"
    component R4: resistor "r_generic_0603" value "330"
